class LegacyLoggerAdapter {          // target shape: log({ level, message })
  #legacy;
  constructor(legacy) { this.#legacy = legacy; }
  log({ level, message }) {
    this.#legacy.log(`${level}: ${message}`);   // translated call
  }
}
client(new LegacyLoggerAdapter(new LegacyLogger()));

